PARAMS = ['R0','kout','Imax','IC50','g']
def predict(df, p):
    def solve_one(dose, ts):
        kin = p['R0']*p['kout']
        def f(t, y):
            c = pk_conc(dose, t)
            return [kin*(1 - p['Imax']*c**p['g']/(p['IC50']**p['g']+c**p['g'])) - p['kout']*y[0]]
        sol = solve_ivp(f, (0, max(ts)), [p['R0']], t_eval=ts, rtol=1e-8, atol=1e-8)
        return sol.y[0]
    return per_dose(df, solve_one)

